using System;using System.IO;using System.Text;using System.Net;using System.Net.Http;using System.Net.Http.Headers;using System.Threading;using System.Threading.Tasks;
namespace ExtremeLand {public sealed partial class Engine {
 static Exception HttpError(HttpResponseMessage r){if((int)r.StatusCode==429||r.StatusCode==HttpStatusCode.Forbidden)return new IOException("El servidor está limitando las descargas. Espera antes de volver a intentar.");if(r.StatusCode==HttpStatusCode.NotFound)return new IOException("La publicación aún no está disponible. Falta publicar channel.json en GitHub Releases.");return new IOException("Descarga fallida (HTTP "+(int)r.StatusCode+").");}
 public async Task<Pack> Fetch(string url,CancellationToken ct){Url(url);string text;var u=new Uri(url);if(TestMode&&u.IsFile)text=File.ReadAllText(u.LocalPath);else{using(var r=await http.GetAsync(url,HttpCompletionOption.ResponseHeadersRead,ct)){if(!r.IsSuccessStatusCode)throw HttpError(r);if(r.Content.Headers.ContentLength>4194304)throw new IOException("Publicación demasiado grande.");using(var stream=await r.Content.ReadAsStreamAsync())using(var mem=new MemoryStream()){byte[] b=new byte[16384];int n;while((n=await stream.ReadAsync(b,0,b.Length,ct))>0){if(mem.Length+n>4194304)throw new IOException("Publicación demasiado grande.");mem.Write(b,0,n);}text=Encoding.UTF8.GetString(mem.ToArray());}}}var pack=Json.S.Deserialize<Pack>(text);Validate(pack);return pack;}
 public async Task<string> Download(string url,string sha,long length,string title,CancellationToken ct){Url(url);string cache=Safe("cache/"+sha);Directory.CreateDirectory(Path.GetDirectoryName(cache));if(File.Exists(cache)&&new FileInfo(cache).Length==length&&Hash(cache)==sha)return cache;string part=cache+".part";long offset=File.Exists(part)?new FileInfo(part).Length:0;if(offset>length){File.Delete(part);offset=0;}
  var uri=new Uri(url);if(TestMode&&uri.IsFile){File.Copy(uri.LocalPath,part,true);Progress(title,length,length);}else{using(var request=new HttpRequestMessage(HttpMethod.Get,url)){if(offset>0)request.Headers.Range=new RangeHeaderValue(offset,null);using(var r=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,ct)){if(r.StatusCode==HttpStatusCode.RequestedRangeNotSatisfiable&&offset==length){}else{if(!r.IsSuccessStatusCode)throw HttpError(r);bool resume=r.StatusCode==HttpStatusCode.PartialContent&&r.Content.Headers.ContentRange!=null&&r.Content.Headers.ContentRange.From==offset;if(!resume)offset=0;using(var input=await r.Content.ReadAsStreamAsync())using(var output=new FileStream(part,offset>0?FileMode.Append:FileMode.Create,FileAccess.Write,FileShare.Read)){byte[] buffer=new byte[262144];int n;long done=offset;var watch=System.Diagnostics.Stopwatch.StartNew();while((n=await input.ReadAsync(buffer,0,buffer.Length,ct))>0){done+=n;if(done>length)throw new IOException("La descarga supera el tamaño esperado.");await output.WriteAsync(buffer,0,n,ct);if(watch.ElapsedMilliseconds>120){Progress(title,done,length);watch.Restart();}}}}}}}
  ct.ThrowIfCancellationRequested();if(!File.Exists(part)||new FileInfo(part).Length!=length||Hash(part)!=sha){if(File.Exists(part))File.Delete(part);throw new IOException("El archivo no pasó la verificación. Vuelve a intentarlo.");}if(File.Exists(cache))File.Delete(cache);File.Move(part,cache);Progress(title,length,length);return cache;
 }
}}
